import{_ as t,o as a,c as s,a4 as l}from"./chunks/framework.BUqnS5H7.js";const g=JSON.parse('{"title":"日志分段与索引","description":"","frontmatter":{},"headers":[],"relativePath":"kafka/reference/chapter-02-log-segment.md","filePath":"kafka/reference/chapter-02-log-segment.md"}'),n={name:"kafka/reference/chapter-02-log-segment.md"};function r(d,e,c,i,f,o){return a(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="日志分段与索引" tabindex="-1" data-src-line="1" data-src-file="kafka/reference/chapter-02-log-segment.md">日志分段与索引 <a class="header-anchor" href="#日志分段与索引" aria-label="Permalink to &quot;日志分段与索引&quot;">​</a></h1><blockquote data-src-line="3" data-src-file="kafka/reference/chapter-02-log-segment.md"><p data-src-line="3" data-src-file="kafka/reference/chapter-02-log-segment.md">每个 Partition 落到磁盘上是一组分段文件与索引。本文是字节级参考，面向需要深入底层的读者。</p></blockquote><h2 id="磁盘布局" tabindex="-1" data-src-line="5" data-src-file="kafka/reference/chapter-02-log-segment.md">磁盘布局 <a class="header-anchor" href="#磁盘布局" aria-label="Permalink to &quot;磁盘布局&quot;">​</a></h2><p data-src-line="7" data-src-file="kafka/reference/chapter-02-log-segment.md">一个 Partition 对应一个目录，目录内以「分段」为单位分文件：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>orders-0/</span></span>
<span class="line"><span>├── 00000000000000000000.log          ← 消息数据文件（FileRecords）</span></span>
<span class="line"><span>├── 00000000000000000000.index        ← 偏移量索引（OffsetIndex）</span></span>
<span class="line"><span>├── 00000000000000000000.timeindex    ← 时间戳索引（TimeIndex）</span></span>
<span class="line"><span>├── 00000000000000000000.snapshot     ← 生产者状态快照（幂等/事务）</span></span>
<span class="line"><span>├── 00000000000000000000.txnindex     ← 已中止事务范围（TransactionIndex）</span></span>
<span class="line"><span>├── 00000000000000001234.log</span></span>
<span class="line"><span>├── 00000000000000001234.index</span></span>
<span class="line"><span>├── 00000000000000001234.timeindex</span></span>
<span class="line"><span>├── 00000000000000005678.log          ← 当前活跃段</span></span>
<span class="line"><span>├── leader-epoch-checkpoint</span></span>
<span class="line"><span>├── partition.metadata</span></span></code></pre></div><p data-src-line="24" data-src-file="kafka/reference/chapter-02-log-segment.md">文件名的 20 位数字是该段的 base offset，左补零。</p><h2 id="类关系" tabindex="-1" data-src-line="26" data-src-file="kafka/reference/chapter-02-log-segment.md">类关系 <a class="header-anchor" href="#类关系" aria-label="Permalink to &quot;类关系&quot;">​</a></h2><table tabindex="0"><thead data-src-line="28" data-src-file="kafka/reference/chapter-02-log-segment.md"><tr data-src-line="28" data-src-file="kafka/reference/chapter-02-log-segment.md"><th style="text-align:left;">抽象</th><th style="text-align:left;">类</th><th style="text-align:left;">职责</th></tr></thead><tbody data-src-line="30" data-src-file="kafka/reference/chapter-02-log-segment.md"><tr data-src-line="30" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">分区日志</td><td style="text-align:left;"><code>UnifiedLog</code></td><td style="text-align:left;">对外的 Partition 日志抽象</td></tr><tr data-src-line="31" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">本地日志</td><td style="text-align:left;"><code>LocalLog</code></td><td style="text-align:left;">只处理本地段的追加、读取、恢复</td></tr><tr data-src-line="32" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">单个分段</td><td style="text-align:left;"><code>LogSegment</code></td><td style="text-align:left;">管一组 <code>.log</code> + <code>.index</code> + <code>.timeindex</code> + <code>.txnindex</code></td></tr><tr data-src-line="33" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">段的数据文件</td><td style="text-align:left;"><code>FileRecords</code></td><td style="text-align:left;">对 <code>.log</code> 的字节读写与 sendfile 传输</td></tr><tr data-src-line="34" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">偏移量索引</td><td style="text-align:left;"><code>OffsetIndex</code></td><td style="text-align:left;">offset → 文件位置</td></tr><tr data-src-line="35" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">时间戳索引</td><td style="text-align:left;"><code>TimeIndex</code></td><td style="text-align:left;">timestamp → offset</td></tr><tr data-src-line="36" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">事务索引</td><td style="text-align:left;"><code>TransactionIndex</code></td><td style="text-align:left;">记录已中止事务的 offset 范围</td></tr></tbody></table><p data-src-line="38" data-src-file="kafka/reference/chapter-02-log-segment.md">来源：<a href="https://github.com/apache/kafka/tree/trunk/storage/src/main/java/org/apache/kafka/storage/internals/log" target="_blank" rel="noreferrer">apache/kafka storage 模块</a></p><h2 id="索引条目结构" tabindex="-1" data-src-line="40" data-src-file="kafka/reference/chapter-02-log-segment.md">索引条目结构 <a class="header-anchor" href="#索引条目结构" aria-label="Permalink to &quot;索引条目结构&quot;">​</a></h2><table tabindex="0"><thead data-src-line="42" data-src-file="kafka/reference/chapter-02-log-segment.md"><tr data-src-line="42" data-src-file="kafka/reference/chapter-02-log-segment.md"><th style="text-align:left;">索引</th><th style="text-align:left;">条目结构</th><th style="text-align:left;">大小</th></tr></thead><tbody data-src-line="44" data-src-file="kafka/reference/chapter-02-log-segment.md"><tr data-src-line="44" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;"><code>OffsetIndex</code></td><td style="text-align:left;">4 字节 relative offset + 4 字节 physical position</td><td style="text-align:left;">8 字节</td></tr><tr data-src-line="45" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;"><code>TimeIndex</code></td><td style="text-align:left;">8 字节 timestamp + 4 字节 relative offset</td><td style="text-align:left;">12 字节</td></tr></tbody></table><p data-src-line="47" data-src-file="kafka/reference/chapter-02-log-segment.md">用「相对 offset」而不是绝对 offset，是为了把每个条目控制在 8 字节内。</p><h2 id="稀疏索引" tabindex="-1" data-src-line="49" data-src-file="kafka/reference/chapter-02-log-segment.md">稀疏索引 <a class="header-anchor" href="#稀疏索引" aria-label="Permalink to &quot;稀疏索引&quot;">​</a></h2><p data-src-line="51" data-src-file="kafka/reference/chapter-02-log-segment.md">Kafka 的索引只在写入若干字节后追加一条，不是每条消息都建。默认每 <code>log.index.interval.bytes = 4096</code> 字节写一条索引项。</p><h3 id="查找过程" tabindex="-1" data-src-line="53" data-src-file="kafka/reference/chapter-02-log-segment.md">查找过程 <a class="header-anchor" href="#查找过程" aria-label="Permalink to &quot;查找过程&quot;">​</a></h3><p data-src-line="55" data-src-file="kafka/reference/chapter-02-log-segment.md">以「查 offset = 1234 的消息」为例：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. 定位段：在 UnifiedLog 的 LogSegments 跳表里二分，找到 base offset ≤ 1234 的段</span></span>
<span class="line"><span>2. 查 OffsetIndex：把 1234 - baseOffset 作为目标相对 offset，二分查最大的 ≤ target 条目</span></span>
<span class="line"><span>   → 假设命中 (relativeOffset = 34, position = 8192)</span></span>
<span class="line"><span>3. 在 FileRecords 里从 position = 8192 开始顺序扫描 RecordBatch</span></span>
<span class="line"><span>   → 每读一批，比较 baseOffset + lastOffsetDelta 是否覆盖 1234</span></span>
<span class="line"><span>4. 命中后按 offsetDelta 定位到具体记录返回</span></span></code></pre></div><p data-src-line="66" data-src-file="kafka/reference/chapter-02-log-segment.md">顺序扫描的长度上界就是索引密度：默认 4096 字节内一定能找到目标。</p><h3 id="mmap-优化" tabindex="-1" data-src-line="68" data-src-file="kafka/reference/chapter-02-log-segment.md">mmap 优化 <a class="header-anchor" href="#mmap-优化" aria-label="Permalink to &quot;mmap 优化&quot;">​</a></h3><p data-src-line="70" data-src-file="kafka/reference/chapter-02-log-segment.md">索引文件通过 <code>MappedByteBuffer</code> 映射进进程虚拟地址空间，查索引不再走 read/write 系统调用。</p><h2 id="分段滚动条件" tabindex="-1" data-src-line="72" data-src-file="kafka/reference/chapter-02-log-segment.md">分段滚动条件 <a class="header-anchor" href="#分段滚动条件" aria-label="Permalink to &quot;分段滚动条件&quot;">​</a></h2><table tabindex="0"><thead data-src-line="74" data-src-file="kafka/reference/chapter-02-log-segment.md"><tr data-src-line="74" data-src-file="kafka/reference/chapter-02-log-segment.md"><th style="text-align:left;">条件</th><th style="text-align:left;">Topic 配置</th><th style="text-align:left;">默认值</th></tr></thead><tbody data-src-line="76" data-src-file="kafka/reference/chapter-02-log-segment.md"><tr data-src-line="76" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">当前段字节数超过阈值</td><td style="text-align:left;"><code>segment.bytes</code></td><td style="text-align:left;">1 GiB</td></tr><tr data-src-line="77" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">当前段存活时间超过阈值</td><td style="text-align:left;"><code>segment.ms</code></td><td style="text-align:left;">7 天</td></tr><tr data-src-line="78" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">索引文件写满</td><td style="text-align:left;"><code>segment.index.bytes</code></td><td style="text-align:left;">10 MiB</td></tr><tr data-src-line="79" data-src-file="kafka/reference/chapter-02-log-segment.md"><td style="text-align:left;">追加消息的相对 offset 无法用 int32 表示</td><td style="text-align:left;">—</td><td style="text-align:left;">硬性上限</td></tr></tbody></table><p data-src-line="81" data-src-file="kafka/reference/chapter-02-log-segment.md">来源：<a href="https://kafka.apache.org/41/configuration/topic-configs" target="_blank" rel="noreferrer">Kafka 4.1 Topic Configs</a></p>`,23)])])}const h=t(n,[["render",r]]);export{g as __pageData,h as default};
